// Keep the existing controls, form values and handlers while navigating settings.
import{t,subscribeLanguage}from './i18n.js';
const sectionLabels=Object.freeze({'settings.city':'city','settings.appearance':'appearance','language.interface':'language','settings.reminders':'reminders','settings.data':'data','settings.application':'application'});
const sectionKeys=new Set(Object.values(sectionLabels));
export function mountSettingsScreens(app,{win=window}={}){
 const doc=app.ownerDocument,form=app.querySelector('#settings-form');if(!form)return()=>{};
 const groups=[...form.querySelectorAll('.settings-grid>.settings-group')],heading=app.querySelector('.page-head h1,.page-title,h1'),save=form.querySelector('.settings-save'),sections=new Map();let disposed=false;
 for(const group of groups){const summary=group.querySelector('summary'),explicit=group.dataset.settingsSection,key=explicit||sectionLabels[summary?.querySelector('[data-i18n]')?.getAttribute('data-i18n')];if(summary&&sectionKeys.has(key)&&!sections.has(key))sections.set(key,{group,summary});}
 const back=doc.createElement('a');back.href='#settings';back.className='settings-screen-back';back.setAttribute('data-i18n','common.backSettings');back.textContent=t('common.backSettings');back.hidden=true;form.before(back);
 function paint(){if(disposed)return;const key=new URLSearchParams(win.location.hash.split('?')[1]||'').get('section'),selected=sections.get(key);app.classList.toggle('settings-section-open',!!selected);back.hidden=!selected;back.textContent=t('common.backSettings');if(heading){const summary=selected?.summary,label=summary?.querySelector('[data-i18n]'),labelKey=label?.getAttribute('data-i18n');if(labelKey||!summary)heading.setAttribute('data-i18n',labelKey||'common.settings');else heading.removeAttribute('data-i18n');heading.textContent=summary?summary.textContent.trim():t('common.settings');}groups.forEach(group=>{const active=selected?.group===group;group.hidden=!!selected&&!active;group.open=active;group.classList.toggle('is-settings-screen',active);});if(save)save.hidden=!selected;}
 const clicks=[...sections].map(([key,{summary}])=>{const handler=e=>{e.preventDefault();const hash='#settings?section='+key;if(win.location.hash!==hash){win.history.pushState(win.history.state,'',hash);win.dispatchEvent(new win.Event('salah:route-history'));}paint();win.scrollTo?.({top:0,left:0,behavior:'instant'});if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}};summary.addEventListener('click',handler);return[summary,handler];});
 const handleRoute=hash=>{if(disposed||!form.isConnected||hash.split('?')[0]!=='#settings')return false;paint();return true;};app.settingsHandleRoute=handleRoute;win.addEventListener('popstate',paint);const offLanguage=subscribeLanguage(paint);paint();return()=>{if(app.settingsHandleRoute===handleRoute)delete app.settingsHandleRoute;disposed=true;offLanguage();win.removeEventListener('popstate',paint);for(const [summary,handler]of clicks)summary.removeEventListener('click',handler);app.classList.remove('settings-section-open');back.remove();};
}
